class Solution {
public:
    int maximizeWin(vector<int>& p, int k) {
        int n = p.size();
        vector<int> win(n);
        for (int i = 0; i < n; i++)
            win[i] = upper_bound(p.begin(), p.end(), p[i] + k) - p.begin() - i;
        vector<int> pref(n + 1, 0);
        int ans = 0;
        for (int i = 0; i < n; i++) {
            ans = max(ans, pref[i] + win[i]);
            pref[i + 1] = max(pref[i], win[i]);
        }
        return ans;
    }
};

