class Solution {
    public int maximizeWin(int[] p, int k) {
        int n = p.length;
        int[] win = new int[n];
        for (int i = 0; i < n; i++) {
            int lo = i, hi = n;
            while (lo < hi) { int mid = (lo + hi) >>> 1; if (p[mid] <= p[i] + k) lo = mid + 1; else hi = mid; }
            win[i] = lo - i;
        }
        int[] pref = new int[n + 1];
        int ans = 0;
        for (int i = 0; i < n; i++) {
            ans = Math.max(ans, pref[i] + win[i]);
            pref[i + 1] = Math.max(pref[i], win[i]);
        }
        return ans;
    }
}

