var maximizeWin = function(p, k) {
    const n = p.length, win = new Array(n);
    const ub = (x) => { let lo = 0, hi = n; while (lo < hi) { const m = (lo + hi) >> 1; if (p[m] <= x) lo = m + 1; else hi = m; } return lo; };
    for (let i = 0; i < n; i++) win[i] = ub(p[i] + k) - i;
    const pref = new Array(n + 1).fill(0);
    let ans = 0;
    for (let i = 0; i < n; i++) {
        ans = Math.max(ans, pref[i] + win[i]);
        pref[i + 1] = Math.max(pref[i], win[i]);
    }
    return ans;
};

