        win = [0] * n
        j = 0
        for i in range(n):
            while prizePositions[i] - prizePositions[j] > k:
                j += 1
            win[i] = i - j + 1
        pref = [0] * (n + 1)
        ans = 0
        for i in range(n):
            ans = max(ans, pref[i] + win[i])
            pref[i + 1] = max(pref[i], win[i])
        return ans

